# The registry is behind SSO/WAF that answers 200 + an HTML login page instead of 401.
# curl -sI the packument URL: a text/html content-type on an unauthenticated GET confirms it.
# .npmrc — send credentials so the proxy passes the request through:
@acme:registry=http://127.0.0.1:4873/
//127.0.0.1:4873/:_authToken=${NPM_TOKEN}

// Verifying an IdP token against a JWKS snapshot held locally (offline JWKS).
import * as jose from 'jose';

const { privateKey, publicKey } = await jose.generateKeyPair('RS256', { extractable: true });
const pub = await jose.exportJWK(publicKey);

const token = await new jose.SignJWT({ sub: 'u1' })
  .setProtectedHeader({ alg: 'RS256', kid: 'idp-key-1' })
  .setIssuedAt().setExpirationTime('10m').sign(privateKey);

// The JWKS entry has the SAME kid as the token header.
const jwks = jose.createLocalJWKSet({
  // BROKEN: keys: [{ ...pub, kid: 'idp-key-1', use: 'enc', alg: 'RS512' }],
  keys: [{ ...pub, kid: 'idp-key-1', use: 'sig', alg: 'RS256' }],
});

const { payload } = await jose.jwtVerify(token, jwks);
if (payload.sub !== 'u1') process.exit(1);
console.log('ok');

// RS256 signing key delivered through an env var (Kubernetes Secret / .env),
// where the PEM newlines arrive escaped as the two characters backslash-n.
import jwt from 'jsonwebtoken';
import crypto from 'node:crypto';

const { privateKey, publicKey } = crypto.generateKeyPairSync('rsa', {
  modulusLength: 2048,
  publicKeyEncoding: { type: 'spki', format: 'pem' },
  privateKeyEncoding: { type: 'pkcs8', format: 'pem' },
});
process.env.JWT_PRIVATE_KEY = privateKey.replace(/\n/g, '<PATH>');

// BROKEN: const key = process.env.JWT_PRIVATE_KEY;
const key = process.env.JWT_PRIVATE_KEY.replace(/<PATH> '\n');

const token = jwt.sign({ sub: 'svc-1' }, key, { algorithm: 'RS256', expiresIn: '10m' });
const claims = jwt.verify(token, publicKey, { algorithms: ['RS256'] });
if (claims.sub !== 'svc-1') process.exit(1);
console.log('ok');

# .npmrc — the auth key host must equal the host in @scope:registry, not the default registry.
@acme:registry=http://127.0.0.1:4873/
//127.0.0.1:4873/:_authToken=${NPM_TOKEN}
# npm sends NO credentials when only //registry.npmjs.org/:_auth or /:_authToken is set.

# .npmrc — legacy bare _auth is rejected by npm >=9. Key it to the registry the SCOPE resolves to,
# not to the default registry that npm names in its own hint.
@acme:registry=http://127.0.0.1:4873/
//127.0.0.1:4873/:_auth=<base64 of user:password>

// check.mjs - undici proxy selection.  run: npm i <STR> && node check.mjs
import http from 'node:http'
import https from 'node:https'
import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'
import { execFileSync } from 'node:child_process'
import { setGlobalDispatcher, ProxyAgent, EnvHttpProxyAgent } from 'undici'

// self-signed TLS material for the internal origin, generated fresh each run
const d = fs.mkdtempSync(path.join(os.tmpdir(), 'nx-'))
execFileSync('openssl', ['req', '-x509', '-newkey', 'rsa:2048', '-nodes', '-days', '1',
  '-subj', '/CN=127.0.0.1', '-addext', 'subjectAltName=IP:127.0.0.1',
  '-keyout', path.join(d, 'k.pem'), '-out', path.join(d, 'c.pem')], { stdio: 'ignore' })
const ca = fs.readFileSync(path.join(d, 'c.pem'))

// internal https service on loopback
const origin = https.createServer({ key: fs.readFileSync(path.join(d, 'k.pem')), cert: ca },
  (_q, s) => s.end('ok')).listen(0, '127.0.0.1')
// corporate proxy that REFUSES to tunnel: 403 to any CONNECT
const proxy = http.createServer((_q, s) => s.end('no'))
proxy.on('connect', (_q, sock) => { sock.write('HTTP/1.1 403 Forbidden\r\n\r\n'); sock.end() })
proxy.listen(0, '127.0.0.1')
await new Promise(r => setTimeout(r, 400))

const purl = 'http://127.0.0.1:' + proxy.address().port
const ourl = 'https://127.0.0.1:' + origin.address().port + '/health'
process.env.HTTP_PROXY = purl
process.env.HTTPS_PROXY = purl
process.env.NO_PROXY = '127.0.0.1'

// BROKEN: ProxyAgent CONNECTs unconditionally and never reads NO_PROXY
// BROKEN: setGlobalDispatcher(new ProxyAgent({ uri: purl, requestTls: { ca } }))
setGlobalDispatcher(new EnvHttpProxyAgent({ connect: { ca } }))

let code = 1
try {
  const r = await fetch(ourl)
  if (r.status === 200 && (await r.text()) === 'ok') { console.log('ok'); code = 0 }
} catch (e) { let x = e; while (x.cause) x = x.cause; console.error(x) }
origin.close(); proxy.close(); fs.rmSync(d, { recursive: true, force: true })
process.exit(code)
